  "Ativando…": { en: "Enabling…", "pt-PT": "Habilitando…", ar: "جارٍ التفعيل…", bn: "সক্ষম করা হচ্ছে...", bg: "Активиране...", hr: "Omogućavanje...", cs: "Povolení…", nl: "Inschakelen…", fr: "Activation…", de: "Aktivieren…", el: "Ενεργοποίηση…", he: "מפעיל...", hu: "Engedélyezés…", id: "Mengaktifkan…", it: "Abilitazione...", pl: "Włączam…", ro: "Se activează…", ru: "Включение…", sk: "Povoľuje sa…", es: "Habilitando…", ta: "இயக்குகிறது...", tr: "Etkinleştiriliyor…", uk: "Увімкнення…", ur: "فعال کر رہا ہے…", nb: "Aktiverer …", ja: "有効化中…", vi: "Đang bật…", zh: "启用..." },
  "{name} desativado.": { en: "{name} disabled.", "pt-PT": "{name} desativado.", ar: "تم تعطيل {name}.", bn: "{name} নিষ্ক্রিয়।", bg: "{name} деактивиран.", hr: "{name} onemogućen.", cs: "{name} zakázáno.", nl: "{name} uitgeschakeld.", fr: "{name} désactivé.", de: "{name} deaktiviert.", el: "{name} απενεργοποιημένο.", he: "{name} מושבת.", hu: "{name} letiltva.", id: "{name} dinonaktifkan.", it: "{name} disabilitato.", pl: "{name} wyłączone.", ro: "{name} dezactivat.", ru: "{name} отключен.", sk: "{name} vypnuté.", es: "{name} deshabilitado.", ta: "{name} முடக்கப்பட்டது.", tr: "{name} devre dışı bırakıldı.", uk: "{name} вимкнено.", ur: "{name} غیر فعال۔", nb: "{name} deaktivert.", ja: "{name} が無効になりました。", vi: "{name} bị vô hiệu hóa.", zh: "{name} 已禁用。" },
  "{name} ativado.": { en: "{name} enabled.", "pt-PT": "{name} ativado.", ar: "تم تفعيل {name}.", bn: "{name} সক্ষম।", bg: "{name} активиран.", hr: "{name} omogućen.", cs: "{name} povoleno.", nl: "{name} ingeschakeld.", fr: "{name} activé.", de: "{name} aktiviert.", el: "{name} ενεργοποιημένο.", he: "{name} מופעל.", hu: "{name} engedélyezve.", id: "{name} diaktifkan.", it: "{name} abilitato.", pl: "{name} włączone.", ro: "{name} activat.", ru: "{name} включен.", sk: "{name} povolené.", es: "{name} habilitado.", ta: "{name} இயக்கப்பட்டது.", tr: "{name} etkin.", uk: "{name} увімкнено.", ur: "{name} فعال ہے۔", nb: "{name} aktivert.", ja: "{name} が有効になりました。", vi: "{name} đã được bật.", zh: "{name} 已启用。" },
  "Mover {name} para cima": { en: "Move {name} up", "pt-PT": "Mover {name} para cima", ar: "نقل {name} إلى الأعلى", bn: "{name} উপরে সরান", bg: "Преместете {name} нагоре", hr: "Pomakni {name} gore", cs: "Posuňte {name} nahoru", nl: "Verplaats {name} omhoog", fr: "Déplacer {name} vers le haut", de: "Verschieben Sie {name} nach oben", el: "Μετακινήστε {name} προς τα πάνω", he: "הזז את {name} למעלה", hu: "A {name} mozgatása felfelé", id: "Pindahkan {name} ke atas", it: "Sposta {name} in alto", pl: "Przesuń {name} w górę", ro: "Mutați {name} în sus", ru: "Переместить {name} вверх", sk: "Posunúť {name} nahor", es: "Mover {name} hacia arriba", ta: "{name} ஐ மேலே நகர்த்தவும்", tr: "{name} yukarıya taşı", uk: "Перемістіть {name} вгору", ur: "{name} اوپر منتقل کریں۔", nb: "Flytt {name} opp", ja: "{name} を上に移動", vi: "Di chuyển {name} lên", zh: "向上移动 {name}" },
  "Mover para cima": { en: "Move up", "pt-PT": "Subir", ar: "نقل إلى الأعلى", bn: "উপরে সরান", bg: "Придвижете се нагоре", hr: "Pomakni se gore", cs: "Posuňte se nahoru", nl: "Ga omhoog", fr: "Monter", de: "Bewegen Sie sich nach oben", el: "Μετακινηθείτε προς τα πάνω", he: "לזוז למעלה", hu: "Lépj felfelé", id: "Naik", it: "Vai su", pl: "Podnieść", ro: "Mișcă-te în sus", ru: "Вверх", sk: "Posunúť sa hore", es: "Subir", ta: "மேலே செல்லவும்", tr: "Yukarı taşı", uk: "Рухатися вгору", ur: "اوپر بڑھیں۔", nb: "Flytt opp", ja: "上に移動", vi: "Di chuyển lên", zh: "向上移动" },
  "Reordenando…": { en: "Reordering…", "pt-PT": "Reordenando…", ar: "جارٍ إعادة الترتيب…", bn: "পুনরায় সাজানো হচ্ছে...", bg: "Пренареждане...", hr: "Promjena redoslijeda...", cs: "Změna pořadí…", nl: "Opnieuw ordenen…", fr: "Réorganisation…", de: "Neuordnung…", el: "Αναπαραγγελία…", he: "מסדר מחדש...", hu: "Átrendezés…", id: "Menyusun ulang…", it: "Riordino…", pl: "Zmiana kolejności…", ro: "Se reordonează…", ru: "Изменение порядка…", sk: "Prebieha zmena poradia…", es: "Reordenando…", ta: "மறுவரிசைப்படுத்துகிறது…", tr: "Yeniden sıralanıyor…", uk: "Перезамовлення…", ur: "دوبارہ ترتیب دے رہا ہے…", nb: "Omorganiserer …", ja: "並べ替え中…", vi: "Đang sắp xếp lại…", zh: "重新排序..." },
