  "Buffer à frente": { en: "Forward buffer", "pt-PT": "Buffer à frente", ar: "المخزن المؤقت للأمام", bn: "সামনের বাফার", bg: "Буфер напред", hr: "Međuspremnik unaprijed", cs: "Vyrovnávací paměť dopředu", nl: "Buffer vooruit", fr: "Tampon avant", de: "Vorwärtspuffer", el: "Buffer προς τα εμπρός", he: "מאגר קדימה", hu: "Előre puffer", id: "Buffer maju", it: "Buffer in avanti", pl: "Bufor do przodu", ro: "Buffer înainte", ru: "Буфер вперёд", sk: "Vyrovnávacia pamäť dopredu", es: "Búfer hacia delante", ta: "முன்னோக்கு இடையகம்", tr: "İleri arabellek", uk: "Буфер вперед", ur: "آگے کا بفر", nb: "Buffer fremover", ja: "先読みバッファー", vi: "Bộ đệm phía trước", zh: "前向缓冲" },
  "Cache em disco": { en: "Disk cache", "pt-PT": "Cache de disco", ar: "ذاكرة على القرص", bn: "ডিস্ক ক্যাশে", bg: "Дисков кеш", hr: "Disk cache", cs: "Disková mezipaměť", nl: "Schijfcache", fr: "Cache disque", de: "Festplatten-Cache", el: "Προσωρινή μνήμη δίσκου", he: "מטמון דיסק", hu: "Lemez gyorsítótár", id: "Tembolok disk", it: "Cache del disco", pl: "Pamięć podręczna dysku", ro: "Cache pe disc", ru: "Дисковый кэш", sk: "Disková vyrovnávacia pamäť", es: "caché de disco", ta: "வட்டு தற்காலிக சேமிப்பு", tr: "Disk önbelleği", uk: "Дисковий кеш", ur: "ڈسک کیش", nb: "Diskbuffer", ja: "ディスクキャッシュ", vi: "Bộ đệm đĩa", zh: "磁盘缓存" },
